import { defineStore } from 'pinia'
import { ref, watch, nextTick } from 'vue'
import { Character, KiokuConstants, correctCharacterParams, relevantCrys } from '../types/KiokuTypes'
import { kiokuData } from '../utils/helpers'
import debounce from "lodash.debounce"
import {
    saveCharacters,
    loadCharacters,
    createCloudUser,
    restoreCloudAccount,
    getSimilarityRelations,
    upsertSimilarity,
    loadCharactersByFriendCode,
    getFriendCode,
    touchLastSeen,
} from "../store/cloud"
import {
    createUserId,
    setUserId,
    getUserId
} from "../store/user"
import { getAccountSimilarityScore } from "../models/AccountSimilarityScore"
import { LuxMagica } from '../types/enums'

const base = {
    ascension: KiokuConstants.minAscension,
    portrait: "",
    kiokuLvl: KiokuConstants.minKiokuLvl,
    magicLvl: KiokuConstants.minMagicLvl,
    heartphialLvl: KiokuConstants.minHeartphialLvl,
    specialLvl: KiokuConstants.minSpecialLvl,
}

const buildCrysOptions = (id: number, stored: Record<string, any> = {}) =>
    Object.fromEntries(
        relevantCrys(id).map(cx => [
            cx.selectionAbilityMstId,
            {
                enabled: false,
                useIndex: 0,
                subCrys: [],
                ...(stored[cx.selectionAbilityMstId] ?? {}),
            }
        ])
    )

export const useCharacterStore = defineStore('characterStore', () => {
    const characters = ref<Character[]>([])

    const charInfo: Record<string, Character> = Object.fromEntries(Object.entries(kiokuData).map(([name, data]) => [name, {
        name,
        id: data.id,
        role: data.role,
        element: data.element,
        supportTarget: data.support_target,
        supportDescription: data.support_effect,
        character_en: data.character_en,
        heartphial: data.heartphial || data.character_en,
        rarity: name === LuxMagica ? 4 : data.rarity,
        obtain: data.obtain,
        permaDate: data.permaDate,
        releaseDate: data.releaseDate,
        isStandardChar: data.obtain === "Permanent",
    }]));

    const basicSetting = (ch: Character) => ({
        enabled: ch.rarity !== 5 || ch.id === 10010101,
        dupes: 0,
        ...base,
    })

    const saved = localStorage.getItem('characters')
    if (saved) {
        const oldChars: Character[] = JSON.parse(saved)
        characters.value = oldChars.map(c => {
            if (c.ascension < 0) c.ascension = KiokuConstants.minAscension
            if (c.ascension > KiokuConstants.maxAscension) c.ascension = KiokuConstants.maxAscension
            if (c.rarity < 5) c.ascension = KiokuConstants.maxAscension
            if (c.name === LuxMagica) c.rarity = 4
            return c
        })
            .filter(k => "name" in k && "id" in k && "enabled" in k && "role" in k && "element" in k && "character_en" in k && "rarity" in k)
            .map(c => ({
                ...basicSetting(c),
                ...Object.fromEntries(Object.entries(c).filter(([k, v]) => v != null)),
                ...charInfo[c.name],
                crysOptions: buildCrysOptions(c.id, c.crysOptions),
            }))
    }

    const PENDING_SYNC_KEY = 'characters_pending_sync'
    const cloudSyncPending = ref<boolean>(localStorage.getItem(PENDING_SYNC_KEY) === 'true')

    const markPending = (val: boolean) => {
        cloudSyncPending.value = val
        localStorage.setItem(PENDING_SYNC_KEY, val ? 'true' : 'false')
    }

    // Per-character `updated_at` this client last confirmed from the cloud
    // (via a load, or a save that went through cleanly). Sent back with
    // every save as a compare-and-swap token so a stale tab/device can't
    // blindly overwrite a change made elsewhere - see save_characters_safe.
    // Kept separate from `characters` so it never leaks into export/import.
    const SYNC_META_KEY = 'characters_sync_meta'
    const syncMeta = ref<Record<number, string>>(
        JSON.parse(localStorage.getItem(SYNC_META_KEY) || '{}')
    )

    const persistSyncMeta = () => {
        localStorage.setItem(SYNC_META_KEY, JSON.stringify(syncMeta.value))
    }

    // Gates cloud saves until this session has either reconciled with the
    // cloud (initializeCloud/loadExistingCloudAccount) or established there's
    // no cloud account to reconcile with. Without this, the synchronous
    // "add any newly-released characters" step below fires the deep watcher
    // at store setup, and its debounce can win a race against the async
    // cloud fetch - saving whatever this session's local storage happened to
    // have before it's had a chance to catch up.
    const hydrated = ref(false)

    let applyingCloudData = false

    const precomputeSimilarities = async () => {
        const userId = getUserId()

        if (!userId) return

        try {
            const myFriendId = await getFriendCode()

            if (!myFriendId) return

            const relatedFriendIds = await getSimilarityRelations(myFriendId)

            await Promise.all(
                relatedFriendIds.map(async (otherFriendId) => {
                    try {
                        const rows = await loadCharactersByFriendCode(otherFriendId)
                        const theirChars = mergeChars(rows) as Character[]

                        const similarity = getAccountSimilarityScore(
                            characters.value,
                            theirChars
                        )

                        await upsertSimilarity(myFriendId, otherFriendId, similarity)
                    } catch (err) {
                        console.error(
                            "Failed to precompute similarity for",
                            otherFriendId,
                            err
                        )
                    }
                })
            )
        } catch (err) {
            console.error("Failed to load similarity relations:", err)
        }
    }

    // After a save, save_characters_safe returns every row's authoritative
    // current state plus a `conflict` flag: true means this client's write
    // for that character was rejected because the server had a newer value
    // than what we last knew about, and the row returned is that server
    // value, not what we sent. Reconciling means folding conflicted rows
    // back into local state (instead of trusting our stale copy) and, for
    // everything else, just recording the fresh updated_at so the next save
    // has an accurate compare-and-swap token.
    const reconcileSaveResult = (result: any) => {
        if (!result?.rows) return

        const conflictRows = result.rows.filter((r: any) => r.conflict)
        const okRows = result.rows.filter((r: any) => !r.conflict)

        if (conflictRows.length) {
            applyCloudCharacters(conflictRows)
        }

        okRows.forEach((r: any) => {
            syncMeta.value[r.character_id] = r.updated_at
        })
        persistSyncMeta()
    }

    const debouncedCloudSave = debounce(async () => {
        try {
            if (!getUserId()) return
            const result = await saveCharacters(characters.value, syncMeta.value)
            markPending(false)
            reconcileSaveResult(result)
            await precomputeSimilarities()
        } catch (err) {
            console.error("Failed to save characters:", err)
        }
    }, 1500)

    const flushPendingSave = () => {
        if (cloudSyncPending.value) {
            debouncedCloudSave.flush()
        }
    }

    watch(
        characters,
        (newVal) => {
            localStorage.setItem('characters', JSON.stringify(newVal))

            if (applyingCloudData) return

            markPending(true)

            // Don't push to the cloud until we've hydrated - see `hydrated`
            // above. The pending flag still gets set, so nothing is lost:
            // once hydration finishes it flushes any pending change itself.
            if (hydrated.value) {
                debouncedCloudSave()
            }
        },
        { deep: true }
    )

    const applyCloudCharacters = (rows: any[]) => {
        applyingCloudData = true
        try {
            rows.forEach((row) => {
                const char = characters.value.find(c => c.id === row.character_id)

                if (row.updated_at) {
                    syncMeta.value[row.character_id] = row.updated_at
                }

                if (!char) return

                Object.assign(
                    char,
                    correctCharacterParams({
                        ...char,
                        enabled: row.enabled,
                        dupes: row.dupes,
                        ascension: row.ascension,
                        kiokuLvl: row.kioku_lvl,
                        magicLvl: row.magic_lvl,
                        heartphialLvl: row.heartphial_lvl,
                        specialLvl: row.special_lvl,
                        portrait: row.portrait,
                        crysOptions: buildCrysOptions(
                            row.character_id,
                            row.crys_options ?? {}
                        ),
                    })
                )
                if (char.name === LuxMagica) char.rarity = 4
            })
            persistSyncMeta()
        } finally {
            // watch(..., { deep: true }) fires on the next tick, not
            // synchronously, so resetting this flag right here (before that
            // tick) makes it a no-op guard - by the time the watcher's
            // callback actually checks it, it's already back to false.
            // Deferring the reset past that tick makes the guard real.
            nextTick(() => { applyingCloudData = false })
        }
    }

    const refreshFromCloud = async () => {
        if (!getUserId() || !hydrated.value) return

        try {
            const rows = await loadCharacters()

            const staleRows = rows.filter((row: any) => {
                const known = syncMeta.value[row.character_id]
                return row.updated_at && (!known || row.updated_at > known)
            })

            if (staleRows.length) {
                applyCloudCharacters(staleRows)
            }
        } catch (err) {
            console.error("Failed to refresh characters from cloud:", err)
        }
    }

    if (typeof document !== 'undefined') {
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'hidden') {
                flushPendingSave()
            } else {
                refreshFromCloud()
            }
        })
        window.addEventListener('pagehide', flushPendingSave)
        window.addEventListener('focus', refreshFromCloud)
    }

    const createCloudAccount = async () => {
        const userId = createUserId()

        await createCloudUser(userId)

        const result = await saveCharacters(characters.value, syncMeta.value)
        markPending(false)
        reconcileSaveResult(result)
        hydrated.value = true

        return userId
    }

    const loadExistingCloudAccount = async (userId: string) => {
        await restoreCloudAccount(userId)

        setUserId(userId)

        const rows = await loadCharacters()

        applyCloudCharacters(rows)
        markPending(false)
        hydrated.value = true
    }

    const initializeCloud = async () => {
        if (!getUserId()) {
            // Nothing to reconcile with - a purely local account is ready
            // to save (to localStorage only) immediately.
            hydrated.value = true
            return
        }

        try {
            if (cloudSyncPending.value) {
                const result = await saveCharacters(characters.value, syncMeta.value)
                markPending(false)
                reconcileSaveResult(result)
            }

            const rows = await loadCharacters()

            if (rows.length > 0) {
                applyCloudCharacters(rows)
            }
        } catch (err) {
            console.error("Failed to initialize cloud characters:", err)
        } finally {
            hydrated.value = true

            // Something may have changed characters.value while we were
            // still hydrating (e.g. newly-released characters getting
            // pushed in at store setup, below) without triggering a save,
            // since the watcher was holding off until now. Flush it.
            if (cloudSyncPending.value) {
                debouncedCloudSave()
            }
        }

        touchLastSeen()
    }

    const toggleCharacter = (id: number) => {
        const char = characters.value.find(c => c.id === id)
        if (char) char.enabled = !char.enabled
    }

    const updateChar = (char: Character) => {
        characters.value[characters.value.findIndex(c => c.id === char.id)] = correctCharacterParams(char);

        characters.value.forEach(c => {
            if (c.heartphial === char.heartphial) {
                c.heartphialLvl = char.heartphialLvl
            }
        })
    }

    const setCharacters = (chars: Character[]) => {
        chars.forEach(updateChar)
    }

    const exportCharacters = () => {
        const dataStr = JSON.stringify(characters.value, null, 2) // pretty JSON
        const blob = new Blob([dataStr], { type: "application/json" })
        const url = URL.createObjectURL(blob)

        const a = document.createElement("a")
        a.href = url
        a.download = "exedraDmgCalcTeam.json"
        a.click()

        URL.revokeObjectURL(url)
    }

    const importCharacters = (file: File) => {
        return new Promise<void>((resolve, reject) => {
            const reader = new FileReader()
            reader.onload = (e) => {
                try {
                    const parsed = JSON.parse(e.target?.result as string)
                    if (Array.isArray(parsed)) {
                        setCharacters(parsed)
                        resolve()
                    } else {
                        reject(new Error("Invalid file format"))
                    }
                } catch (err) {
                    reject(err)
                }
            }
            reader.onerror = () => reject(reader.error)
            reader.readAsText(file)
        })
    }

    Object.entries(charInfo).forEach(([name, data]) => {
        if (!characters.value.map(c => c.name).includes(name)) {
            characters.value.push({
                ...basicSetting(data),
                ...data,
                crysOptions: buildCrysOptions(data.id),
            })
        }
    });

    const mergeChars = (rows: Character[]) => rows.map(c => {
        const chInfo = Object.values(charInfo).find(ch => ch.id === c.id);
        if (!chInfo) return
        return { ...chInfo, ...c }
    })

    return {
        characters,
        toggleCharacter,
        updateChar,
        setCharacters,
        exportCharacters,
        importCharacters,
        createCloudAccount,
        loadExistingCloudAccount,
        initializeCloud,
        mergeChars,
        hydrated,
        cloudSyncPending,
        refreshFromCloud,
    }
})
